seq = open("region.fasta").read().split("\n",1)[1].replace("\n","").upper()

def revcomp(s):
    return s.translate(str.maketrans("ACGT","TGCA"))[::-1]

def find_orfs(s, min_len=90):
    """Return ORFs in the forward sense of the given strand: starts at ATG...stop"""
    stops = {"TAA","TAG","TGA"}
    orfs = []
    for frame in range(3):
        i = frame
        while i < len(s)-2:
            codon = s[i:i+3]
            if codon == "ATG":
                # scan to stop
                j = i
                while j < len(s)-2:
                    c2 = s[j:j+3]
                    if c2 in stops:
                        length = j+3 - i
                        if length >= min_len:
                            orfs.append((i+1, j+3, length, frame+1))
                        break
                    j += 3
                else:
                    # runs to end (no stop)
                    length = len(s) - i
                    orfs.append((i+1, len(s), length, frame+1))
                    j = i+3
                    continue
            i += 3
    return orfs

fwd = find_orfs(seq)
rc = find_orfs(revcomp(seq))
print("Forward strand ORFs (>=90 nt = 30 aa):")
for s0,e,l,f in sorted(fwd, key=lambda x:-x[2])[:15]:
    print(f"  frame f{f}: {s0}-{e}  len {l} nt ({l//3-1} aa)")
print("Reverse strand ORFs:")
for s0,e,l,f in sorted(rc, key=lambda x:-x[2])[:15]:
    print(f"  frame r{f}: {s0}-{e}  len {l} nt ({l//3-1} aa)")
"}

