def revcomp(s):
    return s.translate(str.maketrans("ACGT","TGCA"))[::-1]

def longest_orf_only(s, min_len=90):
    """Find ONE maximal ORF per frame starting at each ATG lazily; efficient version."""
    stops = {"TAA","TAG","TGA"}
    best = []  # (start, end, length, frame)
    for frame in range(3):
        i = frame
        atgs = [k for k in range(frame, len(s)-2, 3) if s[k:k+3]=="ATG"]
        # Next stop codon position at or after each index, precomputed
        # find stop positions
        stops_pos = []
        for k in range(frame, len(s)-2, 3):
            if s[k:k+3] in stops:
                stops_pos.append(k)
        import bisect
        for a in atgs:
            idx = bisect.bisect_left(stops_pos, a)
            if idx < len(stops_pos):
                e = stops_pos[idx]+3
                l = e-a
            else:
                e = len(s)
                l = e-a
            if l >= min_len:
                best.append((a+1, e, l, frame+1))
    return best

fwd = longest_orf_only(seq)
rc = longest_orf_only(revcomp(seq))
print("Forward ORFs>=30aa:", len(fwd))
for s0,e,l,f in sorted(fwd, key=lambda x:-x[2])[:12]:
    print(f"  f{f}: {s0}-{e}  {l} nt  {l//3-1} aa")
print("Reverse ORFs>=30aa:", len(rc))
for s0,e,l,f in sorted(rc, key=lambda x:-x[2])[:12]:
    print(f"  r{f}: {s0}-{e}  {l} nt  {l//3-1} aa")
