# tandem repeats: look for any k-mer (k=6..20) occurring multiple times close together
def tandem_repeats(seq):
    res=[]
    for k in range(4,13):
        for i in range(len(seq)-2*k):
            unit=seq[i:i+k]
            # check if followed by >=1 repeat of unit
            rep=1
            while seq[i+rep*k:i+(rep+1)*k]==unit:
                rep+=1
            if rep>=2 and rep*k>=12:
                end=i+rep*k
                # avoid duplicates (same repeat found with bigger unit)
                res.append((i+1,end,unit,rep,k))
    return res

# Filter: keep only repeats that are NOT also reported as part of a longer-unit repeat or overlapping
raw=tandem_repeats(seq)
# filter those with copies>=3 units OR total>=15bp and unit>=4
filt=[]
for s,e,unit,rep,k in raw:
    if rep>=3 or (rep*k)>=18:
        filt.append((s,e,unit,rep,k))
# dedupe overlaps keeping max k
best=[]
for s,e,unit,rep,k in sorted(filt, key=lambda x:(x[0],-x[4])):
    if best and s <= best[-1][1]:
        continue
    best.append((s,e,unit,rep,k))
print("\nTandem repeats (period>=4, >=3 units or >=18bp):")
for s,e,unit,rep,k in best:
    print(f"  {s}-{e}: unit '{unit}' x{rep} (period {k})")

# Direct repeats (>=10bp) anywhere in sequence
def direct_repeats(seq, minlen=10):
    found=[]
    idx={}
    for k in range(minlen, 14):
        for i in range(len(seq)-k):
            w=seq[i:i+k]
            idx.setdefault(w, []).append(i)
    for w, positions in idx.items():
        if len(positions)>1:
            # take pairs
            pairs = [(a,b) for i,a in enumerate(positions) for b in positions[i+1:] if b-a>=20]
            for a,b in pairs[:3]:
                found.append((a+1, b+1, k, w))
    return sorted(found, key=lambda x:-x[2])

dr = direct_repeats(seq)
print("\nDirect repeats >=10bp (non-overlapping pairs, distance >=20):")
seen=set()
for a,b,k,w in dr:
    if a in seen: continue
    print(f"  len{k}: pos {a} and {b}: {w}")
    seen.add(a)
